public function timeRange(string $format = 'M j H:i'): ?string
    {
        $times = collect($this->allSeries())
            ->flatMap(fn (MetricSeries $series) => $series->points)
            ->pluck('at')
            ->filter()
            ->sort()
            ->values();

        if ($times->isEmpty()) {
            return null;
        }

        return $times->first()->format($format).' – '.$times->last()->format($format).' UTC';
    }

