protected function resolveTableName($table)
    {
        if (! str_contains($table, '\\') || ! class_exists($table)) {
            return $table;
        }

        $model = new $table;

        if (! $model instanceof Model) {
            return $table;
        }

        if (isset(class_uses_recursive($model)[AsPivot::class])) {
            $this->using($table);
        }

        return $model->getTable();
    }

