public function refreshNameLookups()
    {
        $this->nameList = [];

        foreach ($this->allDomainRoutes + $this->allRoutes as $route) {
            if (($name = $route->getName()) && ! $this->inNameLookup($name)) {
                $this->nameList[$name] = $route;
            }
        }
    }

