protected function resolveFeatureName($class, $instance)
    {
        $attribute = (new ReflectionClass($instance))->getAttributes(Name::class)[0] ?? null;

        if ($attribute !== null) {
            return $attribute->newInstance()->name;
        }

        return $instance->name ?? $class;
    }

